"""InduSpace standalone Streamlit application."""
import base64
import gzip

import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(
    page_title="InduSpace | Industrial Property",
    page_icon="🏗️",
    layout="wide",
    initial_sidebar_state="collapsed",
)

st.markdown("""
<style>
  [data-testid="stHeader"], [data-testid="stToolbar"], #MainMenu, footer { display: none; }
  [data-testid="stAppViewContainer"] > .main { padding: 0; }
  [data-testid="stMainBlockContainer"] { max-width: none; padding: 0; }
  [data-testid="stIFrame"] iframe { border: 0; }
</style>
""", unsafe_allow_html=True)

HTML_BUNDLE = """"""
html = gzip.decompress(base64.b64decode(HTML_BUNDLE)).decode("utf-8")

components.html(html, height=3600, scrolling=True)
